import{_ as a,o as n,c as i,a5 as t}from"./chunks/framework.CXroN2RO.js";const h=JSON.parse('{"title":"リンクエラー — 未解決外部シンボル・多重定義・ABI互換性","description":"","frontmatter":{"title":"リンクエラー — 未解決外部シンボル・多重定義・ABI互換性","study":{"source":"C++ Wiki","status":"published","summary":"リンクエラーはC++入門者を最も絶望させるエラーですが、原因はほぼ3パターンです。仕組み(シンボルとリンケージ)を前提に、症状→原因→処方の逆引きとしてまとめます。 意味: 「この関数を呼ぶコードはあるが、定義(実体)がどの.o/ライブラリにもない」。コンパイルは通っている(宣言はあった)ことに注意","section":"reference","format":"article","domain":"tools"}},"headers":[],"relativePath":"tools/build/link-errors.md","filePath":"tools/build/link-errors.md"}'),l={name:"tools/build/link-errors.md"};function s(o,e,r,d,p,c){return n(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="リンクエラー-—-未解決外部シンボル・多重定義・abi互換性" tabindex="-1">リンクエラー — 未解決外部シンボル・多重定義・ABI互換性 <a class="header-anchor" href="#リンクエラー-—-未解決外部シンボル・多重定義・abi互換性" aria-label="Permalink to &quot;リンクエラー — 未解決外部シンボル・多重定義・ABI互換性&quot;">​</a></h1><p>リンクエラーはC++入門者を最も絶望させるエラーですが、原因は<strong>ほぼ3パターン</strong>です。仕組み(<a href="/study/runtime/cpp-internals/symbols-and-linkage.html">シンボルとリンケージ</a>)を前提に、症状→原因→処方の逆引きとしてまとめます。</p><h2 id="パターン1-未解決外部シンボル-undefined-reference-lnk2019" tabindex="-1">パターン1: 未解決外部シンボル (undefined reference / LNK2019) <a class="header-anchor" href="#パターン1-未解決外部シンボル-undefined-reference-lnk2019" aria-label="Permalink to &quot;パターン1: 未解決外部シンボル (undefined reference / LNK2019)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>undefined reference to \`Enemy::TakeDamage(int)&#39;        (GCC/Clang)</span></span>
<span class="line"><span>error LNK2019: 未解決の外部シンボル &quot;public: void __cdecl Enemy::TakeDamage(int)&quot;  (MSVC)</span></span></code></pre></div><p><strong>意味</strong>: 「この関数を呼ぶコードはあるが、<strong>定義(実体)がどの.o/ライブラリにもない</strong>」。コンパイルは通っている(宣言はあった)ことに注意——<a href="/study/runtime/cpp-internals/build-pipeline-journey.html">ビルドの旅</a>の④で起きる病気です。</p><p>チェックリスト(頻度順):</p><ol><li><strong>定義を書き忘れ / .cppをビルド対象に入れ忘れ</strong>(CMakeのソースリスト漏れ)</li><li><strong>ライブラリをリンクしていない</strong>(<code>-lfmod</code> を書いていない、.libを追加していない)</li><li><strong>リンク順</strong>(GNU ld系はコマンドラインの左から右に解決。ライブラリは<strong>使う側より後ろ</strong>に書く)</li><li><strong>宣言と定義のシグネチャ不一致</strong>(<code>void Foo(int)</code> を宣言、<code>void Foo(long)</code> を定義——別シンボルになる)</li><li><strong>テンプレートの定義が.cppにある</strong>(実体化できない → ヘッダーへ移す。→ <a href="/study/runtime/cpp-internals/template-instantiation-and-inline.html">実体化</a>)</li><li>C++からCの関数を呼んでいて <code>extern &quot;C&quot;</code> がない(名前修飾の不一致)</li><li>仮想デストラクタやvtable絡み: <code>undefined reference to vtable for X</code> は<strong>キー仮想関数(最初の非inline仮想関数)の定義漏れ</strong>のサイン</li></ol><h2 id="パターン2-多重定義-multiple-definition-lnk2005" tabindex="-1">パターン2: 多重定義 (multiple definition / LNK2005) <a class="header-anchor" href="#パターン2-多重定義-multiple-definition-lnk2005" aria-label="Permalink to &quot;パターン2: 多重定義 (multiple definition / LNK2005)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>multiple definition of \`g_config&#39;</span></span>
<span class="line"><span>error LNK2005: &quot;int g_score&quot; は既に main.obj で定義されています</span></span></code></pre></div><p><strong>意味</strong>: <a href="/study/runtime/cpp-internals/translation-units-and-headers.html">ODR</a>違反。同じ定義が複数の.oに存在。</p><p>チェックリスト:</p><ol><li><strong>ヘッダーに非inline関数の定義</strong>を書いた → inlineを付けるか.cppへ</li><li><strong>ヘッダーにグローバル変数の定義</strong>(<code>int g_score;</code>)→ <code>inline int g_score = 0;</code>(C++17)か、ヘッダーはexternの宣言+.cppで定義</li><li>include guardの欠如(同一翻訳単位内の再定義はコンパイルエラーとして出る)</li><li>Unity Build導入時のstatic/名前の衝突(→ <a href="/study/tools/build/build-speed.html">ビルド時間</a>)</li></ol><h2 id="パターン3-abi・実行時のリンク問題" tabindex="-1">パターン3: ABI・実行時のリンク問題 <a class="header-anchor" href="#パターン3-abi・実行時のリンク問題" aria-label="Permalink to &quot;パターン3: ABI・実行時のリンク問題&quot;">​</a></h2><p>リンクは通ったのに壊れる/特殊なリンクエラーが出る、上級の病気(→ <a href="/study/runtime/cpp-internals/symbols-and-linkage.html">ABI</a>)。</p><ol><li><strong>設定違いのバイナリ混在</strong>: MSVCでDebugとReleaseのライブラリを混ぜる(イテレータサイズが違い、LNK2038「_ITERATOR_DEBUG_LEVELの不一致」や実行時破壊)。CRTの静的/動的(/MT vs /MD)混在も同種</li><li><strong>ABIやファイル形式の不一致</strong>: MinGW製のC++ライブラリとMSVCプロジェクトなど。コンパイラ名だけでなく、公開型・標準ライブラリ・呼出規約・対象CPUを確認する。C ABIに絞った連携とは条件が異なる</li><li><strong>ライブラリのビルド時と使用時でヘッダーのバージョンが違う</strong>: 構造体レイアウトが変わっていて、リンクは通るが実行時にメンバがズレて壊れる(検出困難な最悪ケース。ライブラリ更新時はクリーンビルド)</li><li>DLL境界のC++型・CRT跨ぎのnew/delete(→ <a href="/study/runtime/cpp-internals/object-files-and-libraries.html">DLL</a>)</li></ol><h2 id="デバッグの道具" tabindex="-1">デバッグの道具 <a class="header-anchor" href="#デバッグの道具" aria-label="Permalink to &quot;デバッグの道具&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nm -C libgame.a | grep TakeDamage      # このライブラリは該当シンボルを「提供(T)」しているか「要求(U)」か</span></span>
<span class="line"><span>objdump -t / dumpbin /symbols          # 同上(MSVC)</span></span>
<span class="line"><span>c++filt &quot;_ZN5Enemy10TakeDamageEi&quot;      # 修飾名の復元</span></span>
<span class="line"><span>リンカの詳細ログ: -Wl,--verbose / /VERBOSE   # どのライブラリをどの順で見たか</span></span></code></pre></div><p>「<strong>そのシンボルを、誰が要求し、誰が提供しているはずか</strong>」を機械的に確認する——勘ではなくシンボル表で戦うのが上達の近道です。</p><h2 id="c-unityとの対応" tabindex="-1">C#/Unityとの対応 <a class="header-anchor" href="#c-unityとの対応" aria-label="Permalink to &quot;C#/Unityとの対応&quot;">​</a></h2><ul><li>C#のマネージドアセンブリは、ヘッダー/オブジェクトファイルを結ぶC++と異なる方式で型を参照する。一方で、参照や対象APIの不一致、実行時のアセンブリ読み込み失敗、必要な型/メソッドの不足は起こる。ネイティブプラグインにはDLLの所在・対象CPU・ABI・シンボルの条件もある</li><li>Unityの<strong>IL2CPPビルド時のネイティブリンクエラー</strong>(プラグインのシンボル不足など)は本ページの例に対応する。strippingで必要な管理コードが除かれる問題は区別し、必要に応じてlink.xml等で保持する(→ <a href="/study/languages/csharp/il2cpp.html">IL2CPP</a>)</li><li>UEでは「モジュールの依存(Build.csのDependencyModuleNames)書き忘れ」が未解決シンボルの主因(→ <a href="/study/game/unreal/build-system-ubt.html">Unreal Build Tool・Module・Build.cs・Target.cs</a>)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>「コンパイルは通ったのにリンクで落ちる」が起こる仕組みを説明できますか。</li><li>undefined reference の原因トップ3は?</li><li>「リンクは通るが実行時に壊れる」ABI問題の例を1つ挙げてください。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p><a href="/study/tools/build/samples/tu-demo.html">samples/tu_demo/</a> で意図的に、(a) enemy.cppをリンク対象から外して未解決外部シンボル、(b) enemy.hの関数からinlineを外して多重定義、を再現し、エラーメッセージからシンボル名を読み取って原因を特定する練習をしてください。</p><hr><p>関連項目：<a href="/study/tools/build/debugging-and-analysis.html">品質のための道具</a> / <a href="/study/tools/build/">学習ガイド</a> / <a href="/study/tools/build/exercises.html">演習</a></p>`,26)])])}const g=a(l,[["render",s]]);export{h as __pageData,g as default};
